/**
 * profileService.js — profile endpoint (v2)
 */
import { request } from '../utils/http';

const getToken = () => localStorage.getItem('nmc_token');

export const profileService = {
  getProfile: () =>
    request({ url: '/api/v2/profile', headers: { Authorization: `Bearer ${getToken()}` } }),

  updateProfile: ({ first_name, last_name }) =>
    request({
      url: '/api/v2/profile',
      method: 'PATCH',
      headers: { Authorization: `Bearer ${getToken()}` },
      body: { first_name, last_name },
    }),
};
