/**
 * adminApiV1.js — legacy enrollment API
 * Base path: /admin/api/v1
 */
import { request } from '../utils/http';

const getToken = () => localStorage.getItem('nmc_token');

export const adminApiV1 = {
  /**
   * POST /admin/api/v1/register
   */
  register: (data) =>
    request({ url: '/admin/api/v1/register', method: 'POST', body: data }),

  /** PATCH /admin/api/v1/profile */
  updateProfile: (data) =>
    request({
      url: '/admin/api/v1/profile',
      method: 'PATCH',
      headers: { Authorization: `Bearer ${getToken()}` },
      body: data,
    }),

  /** POST /admin/api/v1/auth/forgot-password */
  forgotPassword: (email) =>
    request({ url: '/admin/api/v1/auth/forgot-password', method: 'POST', body: { email } }),

  /** POST /admin/api/v1/academy/users */
  createAcademyUser: (data) =>
    request({
      url: '/admin/api/v1/academy/users',
      method: 'POST',
      headers: { Authorization: `Bearer ${getToken()}` },
      body: data,
    }),

  /** GET /admin/api/v1/applicants */
  getApplicants: () =>
    request({ url: '/admin/api/v1/applicants', headers: { Authorization: `Bearer ${getToken()}` } }),
};
