/**
 * authService.js — public authentication endpoints (v2)
 */
import { request } from '../utils/http';

export const authService = {
  register: (data) =>
    request({ url: '/api/v2/register', method: 'POST', body: data }),

  login: (email, password) =>
    request({ url: '/api/v2/auth/login', method: 'POST', body: { email, password } }),

  logout: () => {
    localStorage.removeItem('nmc_token');
    window.location = '/login';
  },

  forgotPassword: (email) =>
    request({ url: '/api/v2/auth/forgot-password', method: 'POST', body: { email } }),

  resetPassword: (token, password) =>
    request({ url: '/api/v2/auth/reset-password', method: 'POST', body: { token, password } }),
};
